import { cx } from '@/lib/cx';
import './distribution-strip.css';

/**
 * B44 · DistributionStrip — the named replacement for the donut (Firewall
 * A2 bans donut, pie, radial and gauge). It states how ONE total divides
 * into its parts. This is NOT B6 MeterList, which the Book pointed at
 * until now: B6 measures each part against ITS OWN maximum — utilization,
 * "Zone A is 92% full" — while B44 divides ONE total into shares, "46% of
 * 128,953 sessions were mobile". Neither is a donut and neither ever will
 * be. The strip is one flat bar with structural 2px seams, because a
 * gradient smear would read as a continuum instead of as parts; the legend
 * is the data and repeats every figure as text, so nothing is carried by
 * colour or width alone (C5).
 *
 * Don'ts: never more than five rows — six parts is a B7 DataTable; never a
 * stack of strips comparing periods — that is B5 kind="stacked"; never a
 * strip whose parts do not sum to the stated total without saying so.
 */
export interface DistributionPart {
  label: string;
  value: number;
}

export interface DistributionStripProps {
  /** REQUIRED takeaway, e.g. "Devices accessed, 128,953 total: mobile 46%, desktop 31%, tablet 15%, other 8%". */
  ariaLabel: string;
  /** Mono uppercase label for the total, e.g. "DEVICES ACCESSED". */
  label: string;
  parts: DistributionPart[];
  /** Defaults to the sum of the parts. Pass it when the parts are a subset. */
  total?: number;
  /** Formats both the total and each absolute figure. Defaults to a grouped integer. */
  format?: (value: number) => string;
  className?: string;
}

/** Four named tones, in order. A fifth part is the caller's "Other" and reuses the last. */
const TONES = ['seed', 'compare', 'faint', 'edge'] as const;

/* Resolved per call, never at module scope: a formatter built at import
   time freezes whatever locale the module happened to load under. */
const groupedInteger = (value: number) => value.toLocaleString();

export function DistributionStrip({
  ariaLabel,
  label,
  parts,
  total,
  format = groupedInteger,
  className,
}: DistributionStripProps) {
  const sum = parts.reduce((acc, part) => acc + part.value, 0);
  const denominator = total ?? sum;
  const share = (value: number) => (denominator > 0 ? (value / denominator) * 100 : 0);
  const tone = (i: number) => TONES[Math.min(i, TONES.length - 1)];

  return (
    <div className={cx('sv-dist', className)}>
      <div className="sv-dist__line">
        <span className="sv-dist__label sv-mono">{label}</span>
        <span className="sv-dist__total sv-num">{format(denominator)}</span>
      </div>
      <div className="sv-dist__strip" role="img" aria-label={ariaLabel}>
        {parts.map((part, i) => (
          <span
            key={part.label}
            className={cx('sv-dist__seg', `sv-dist__tone--${tone(i)}`)}
            style={{ flexBasis: `${share(part.value)}%` }}
          />
        ))}
      </div>
      <ul className="sv-dist__legend">
        {parts.map((part, i) => (
          <li key={part.label} className="sv-dist__row">
            <span className={cx('sv-dist__swatch', `sv-dist__tone--${tone(i)}`)} aria-hidden="true" />
            <span className="sv-dist__name">{part.label}</span>
            {/* The absolute figure is REQUIRED beside the share, exactly as in B6. */}
            <span className="sv-dist__figure sv-num">
              {format(part.value)} · {Math.round(share(part.value))}%
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/* B44 · DistributionStrip — one total split into parts, with structural
   seams instead of a gradient, and a legend that carries every number. */

@layer sv-components {
  .sv-dist {
    display: flex;
    flex-direction: column;
    gap: var(--sv-s2);
  }

  .sv-dist__line {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--sv-s3);
  }

  .sv-dist__label {
    color: var(--sv-ink-soft);
  }

  /* B4's value voice — the figure, not the bar, is the information. */
  .sv-dist__total {
    font-size: 19px;
    font-weight: 700;
  }

  /* The wall shows through when the parts are a subset of the total. */
  .sv-dist__strip {
    display: flex;
    height: 10px;
    border-radius: 2px;
    background: var(--sv-wall);
    overflow: hidden;
  }

  /* The 2px paper seam is what makes this read as PARTS. It is structure,
     not decoration: without it the strip is one continuous smear. */
  .sv-dist__seg {
    flex-grow: 0;
    flex-shrink: 0;
    min-width: 0;
    border-right: 2px solid var(--sv-paper);
  }

  .sv-dist__seg:last-child {
    border-right: 0;
  }

  .sv-dist__legend {
    display: flex;
    flex-direction: column;
    gap: var(--sv-s2);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .sv-dist__row {
    display: flex;
    align-items: baseline;
    gap: var(--sv-s2);
  }

  .sv-dist__swatch {
    flex: none;
    width: 8px;
    height: 8px;
    border-radius: 2px;
  }

  .sv-dist__name {
    font-size: 12.5px;
    font-weight: 500;
    color: var(--sv-ink);
  }

  .sv-dist__figure {
    margin-left: auto;
    font-size: 11px;
    color: var(--sv-ink-soft);
  }

  .sv-dist__tone--seed    { background: var(--sv-seed); }
  .sv-dist__tone--compare { background: var(--sv-compare); }
  .sv-dist__tone--faint   { background: var(--sv-ink-faint); }
  /* The fourth tone is --sv-field-line-strong, NOT the hairline: it is the
     last distinguishable step (3.63:1 on paper) and a segment drawn at
     --sv-line would be 1.06:1 — a part of the total that nobody can see is
     a part that was not stated (WCAG 1.4.11). The hairline stays what it is:
     a rule, not a fill. */
  .sv-dist__tone--edge    { background: var(--sv-field-line-strong); }

  /* ---- v0.9 · the strip arrives, and it is OFF until the app asks ----

     Each SEGMENT scales from its own left edge, not the strip from its
     left edge, and the difference is structural rather than aesthetic.
     Scaling `.sv-dist__strip` would scale the 2px paper seams with it —
     the seams are what makes this read as PARTS instead of one
     continuous smear, so an entrance that thins them to nothing spends
     its 200ms dismantling the component's only structural claim. Scaling
     the segments leaves every seam at 2px on every frame; what grows is
     the fill on either side of it.

     The --sv-wall track shows through underneath while they draw, which
     is the same thing it does at rest when the parts are a subset of the
     total. Nothing new appears mid-animation.

     No stagger — see meter-list.css. And B44 is the component that
     already passes this surface's test by specification: "delete the
     strip and the card still answers the question", because the legend
     under it repeats every part by name and figure. A strip that draws
     in is that same illustration, arriving. */
  [data-motion='on'] .sv-dist__seg {
    transform-origin: left center;
    animation: sv-dist-grow var(--sv-t-enter) cubic-bezier(0.215, 0.61, 0.355, 1);
  }

  @keyframes sv-dist-grow {
    from {
      transform: scaleX(0);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-motion='on'] .sv-dist__seg {
      animation: none;
    }
  }
}
